.nav-links a:hover{background:var(--hover);text-decoration:none}
.nav-actions{display:flex;gap:8px;align-items:center}
.btn{padding:8px 18px;border-radius:8px;font-size:13px;font-weight:600;border:none;cursor:pointer;transition:all .15s}
.btn-outline{background:transparent;border:1px solid var(--border);color:var(--navy)}
.btn-outline:hover{border-color:var(--gray)}
.btn-primary{background:var(--blue);color:#fff}
.btn-primary:hover{background:#2d4fd7}

/* TOP BAR METRICS */
.metrics-bar{background:var(--bg-alt);border-bottom:1px solid var(--border);padding:10px 0;font-size:12px}
.metrics-inner{display:flex;gap:24px;align-items:center;flex-wrap:wrap}
.metric{display:flex;align-items:center;gap:6px;white-space:nowrap}
.metric-label{color:var(--gray);font-weight:500}
.metric-value{font-weight:600;font-variant-numeric:tabular-nums}
.metric .up{color:var(--green)}
.metric .down{color:var(--red)}
.fear-gauge{display:inline-flex;align-items:center;gap:4px}
.fear-bar{width:40px;height:6px;border-radius:3px;background:linear-gradient(90deg,var(--red),#f5a623,var(--green));position:relative}
.fear-dot{width:8px;height:8px;border-radius:50%;background:var(--navy);border:2px solid #fff;position:absolute;top:-1px;left:53%;transform:translateX(-50%)}

/* PROMO BANNER */
