.promo-slide{min-width:100%;text-align:center;font-size:13px;font-weight:500}
.promo-slide a{color:#7eb5ff}
.promo-dots{display:flex;justify-content:center;gap:6px;margin-top:8px}
.promo-dot{width:6px;height:6px;border-radius:50%;background:rgba(255,255,255,.3);cursor:pointer;border:none}
.promo-dot.active{background:#fff}

/* AI BAR */
