.page-btn{min-width:36px;height:36px;display:flex;align-items:center;justify-content:center;border-radius:8px;border:1px solid var(--border);background:var(--bg);font-size:13px;font-weight:500;cursor:pointer;color:var(--navy);transition:all .15s}
.page-btn:hover{border-color:var(--blue);color:var(--blue)}
.page-btn.active{background:var(--blue);color:#fff;border-color:var(--blue)}
