  if(v>=1e12) return '$'+(v/1e12).toFixed(2)+'T';
  if(v>=1e9) return '$'+(v/1e9).toFixed(2)+'B';
  if(v>=1e6) return '$'+(v/1e6).toFixed(2)+'M';
  return '$'+v.toLocaleString();
}
function pctClass(v){return v>0?'pct-up':v<0?'pct-down':'pct-flat'}
function pctStr(v){return (v>=0?'+':'')+v.toFixed(2)+'%'}

function genSparkline(d7,color){
  const w=120,h=40,pts=14;
  const seed=Math.abs(d7*1000)%100;
  let vals=[];
  for(let i=0;i<pts;i++){
    const base=50+d7*2;
    const noise=Math.sin(seed+i*0.7)*10+Math.cos(seed*0.3+i)*5;
    vals.push(base+noise+(i/pts)*d7*3);
  }
  const mn=Math.min(...vals),mx=Math.max(...vals),rng=mx-mn||1;
  const points=vals.map((v,i)=>{
    const x=(i/(pts-1))*w;
    const y=h-4-((v-mn)/rng)*(h-8);
    return `${x.toFixed(1)},${y.toFixed(1)}`;
  }).join(' ');
  const fillPts=`0,${h} ${points} ${w},${h}`;
  const lineColor=d7>=0?'var(--green)':'var(--red)';
  const fillColor=d7>=0?'rgba(22,199,132,.08)':'rgba(234,57,67,.08)';
  return `<svg class="sparkline" viewBox="0 0 ${w} ${h}"><polygon points="${fillPts}" fill="${fillColor}"/><polyline points="${points}" fill="none" stroke="${lineColor}" stroke-width="1.5"/></svg>`;
}

let currentData=cryptos;
