  <td class="align-r price col-price">${fmtPrice(c.price)}</td>
  <td class="align-r col-1h"><span class="${pctClass(c.h1)}">${pctStr(c.h1)}</span></td>
  <td class="align-r col-24h"><span class="${pctClass(c.h24)}">${pctStr(c.h24)}</span></td>
  <td class="align-r col-7d"><span class="${pctClass(c.d7)}">${pctStr(c.d7)}</span></td>
