  <td class="align-r col-chart">${genSparkline(c.d7,c.color)}</td>
</tr>`).join('');
}

// Category tabs
document.getElementById('categoryTabs').addEventListener('click',e=>{
  const btn=e.target.closest('.tab-btn');
  if(!btn)return;
  document.querySelectorAll('#categoryTabs .tab-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  const cat=btn.dataset.cat;
  if(cat==='top'){currentData=cryptos;renderTable(currentData);return}
  if(cat==='trending'){
    currentData=[...cryptos].sort((a,b)=>b.d7-a.d7).slice(0,20);
  }else if(cat==='watchlist'){
    currentData=cryptos.filter((_,i)=>i<5);
  }else if(cat==='new'){
    currentData=[...cryptos].slice(-20).reverse();
  }else if(cat==='visited'){
    currentData=cryptos.filter((_,i)=>i<15);
  }else if(cat==='prediction'){
    currentData=cryptos.filter(c=>['ONDO','WLD','PYTH','PENDLE','DYDX'].includes(c.sym));
  }else{
    currentData=cryptos;
  }
  renderTable(currentData);
});

// Network tabs
document.getElementById('networkTabs').addEventListener('click',e=>{
  const btn=e.target.closest('.tab-btn');
  if(!btn)return;
  document.querySelectorAll('#networkTabs .tab-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
